#!/usr/bin/env bash
# Generated by ChatGPT
set -euo pipefail

cd "$(dirname "$0")"

PROJECT_ID="cs528-project-0-508215"
REGION="us-east1"
ZONE="us-east1-b"
SQL_INSTANCE="hw5-db"
BUCKET_NAME="ec528hw2"

SA_NAME="hw6-models"
SA_EMAIL="$SA_NAME@$PROJECT_ID.iam.gserviceaccount.com"
VM_NAME="hw6-models-$(date +%Y%m%d-%H%M%S)"
VM_CREATED=0

cleanup() {
    local failed=0

    if [ "$VM_CREATED" -eq 1 ]; then
        echo "Deleting VM: $VM_NAME"
        gcloud compute instances delete "$VM_NAME" \
            --zone="$ZONE" --project="$PROJECT_ID" --quiet \
            || failed=1
    fi

    echo "Stopping database: $SQL_INSTANCE"
    gcloud sql instances patch "$SQL_INSTANCE" \
        --activation-policy=NEVER \
        --project="$PROJECT_ID" --quiet \
        || failed=1

    rm -f .hw6.env
    return "$failed"
}

read -r -s -p "Database password: " DB_PASSWORD
echo

umask 077
{
    printf 'INSTANCE_CONNECTION_NAME=%q\n' \
        "$PROJECT_ID:$REGION:$SQL_INSTANCE"
    printf 'DB_USER=%q\n' "postgres"
    printf 'DB_NAME=%q\n' "hw5"
    printf 'DB_PASSWORD=%q\n' "$DB_PASSWORD"
    printf 'BUCKET_NAME=%q\n' "$BUCKET_NAME"
    printf 'GOOGLE_CLOUD_PROJECT=%q\n' "$PROJECT_ID"
} > .hw6.env
unset DB_PASSWORD

# Also clean up if a later command fails.
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

if ! gcloud iam service-accounts describe "$SA_EMAIL" \
    --project="$PROJECT_ID" >/dev/null 2>&1
then
    gcloud iam service-accounts create "$SA_NAME" \
        --display-name="HW6 models" \
        --project="$PROJECT_ID"
fi

gcloud projects add-iam-policy-binding "$PROJECT_ID" \
    --member="serviceAccount:$SA_EMAIL" \
    --role="roles/cloudsql.client" \
    --condition=None --quiet --format=none

gcloud storage buckets add-iam-policy-binding "gs://$BUCKET_NAME" \
    --member="serviceAccount:$SA_EMAIL" \
    --role="roles/storage.objectUser" \
    --condition=None --quiet --format=none

echo "Starting database..."
gcloud sql instances patch "$SQL_INSTANCE" \
    --activation-policy=ALWAYS \
    --project="$PROJECT_ID" --quiet

echo "Creating VM: $VM_NAME"
gcloud compute instances create "$VM_NAME" \
    --zone="$ZONE" \
    --machine-type=e2-standard-2 \
    --image-family=debian-12 \
    --image-project=debian-cloud \
    --boot-disk-size=10GB \
    --boot-disk-type=pd-standard \
    --service-account="$SA_EMAIL" \
    --scopes=cloud-platform \
    --project="$PROJECT_ID" --quiet

VM_CREATED=1

# Wait for the new VM to accept SSH connections.
SSH_READY=0
for attempt in {1..12}; do
    if gcloud compute ssh "$VM_NAME" \
        --zone="$ZONE" --project="$PROJECT_ID" --quiet \
        --command="mkdir -p ~/hw6"
    then
        SSH_READY=1
        break
    fi
    echo "Waiting for SSH..."
    sleep 10
done

if [ "$SSH_READY" -ne 1 ]; then
    echo "Could not connect to the VM."
    exit 1
fi

gcloud compute scp \
    models.py requirements.txt vm-run.sh .hw6.env \
    "$VM_NAME:~/hw6/" \
    --zone="$ZONE" --project="$PROJECT_ID" --quiet

gcloud compute ssh "$VM_NAME" \
    --zone="$ZONE" --project="$PROJECT_ID" --quiet \
    --command="cd ~/hw6 && sed -i 's/\r$//' vm-run.sh .hw6.env requirements.txt && bash vm-run.sh"

# Normal completion: clean up before displaying the bucket results.
cleanup
trap - EXIT INT TERM

echo "Country predictions from the bucket:"
gcloud storage cat "gs://$BUCKET_NAME/hw6/country_predictions.csv"

echo "Income predictions from the bucket:"
gcloud storage cat "gs://$BUCKET_NAME/hw6/income_predictions.csv"

echo "Final metrics from the bucket:"
gcloud storage cat "gs://$BUCKET_NAME/hw6/metrics.json"

echo
echo "HW6 completed. Database stopped and VM deleted."